const component=(id,label,weight,aggregate=false)=>({id,label,weight,max:100,aggregate,raw:!aggregate});
const grading=(id,pass,components,options={})=>({mode:'weighted-percentage',source:SYLLABUS_SOURCES[id].file+' · pp. '+SYLLABUS_SOURCES[id].gradingPages.join(', '),edition:SYLLABUS_SOURCES[id].edition,passingPercentage:pass,components,defaultTarget:components.find(c=>c.id==='final')?.id||components.at(-1).id,...options});
const calculus=id=>grading(id,55,[component('quizzes','Long-quiz category average (4 quizzes)',55,true),component('final','Final examination',30),component('activities','Activity-sheet category grade',5,true),component('project','Course project',5),component('teacher','Teacher’s evaluation',5)]);
const physics=(id,count)=>grading(id,50,[component('exams',`Long-exam category average (${count} exams)`,35,true),component('final','Final examination',50),component('product','Final product / assignments',15,true)],{mode:'higher-exam-weight',comparison:{ids:['exams','final'],higher:50,lower:35},note:'The higher of the long-exam average and final-exam percentage receives 50%; the other receives 35%. The final product contributes 15%.'});
const requirements=(...rows)=>rows.map(([id,label,source])=>({id,label,source}));
